using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using LighFight.Runtime;
namespace LighFight.Editor{
// Test-only. Uses existing main runtime classes; regenerates all script references with AssetDatabase APIs.
public static class TripoPlayableCandidateBuilder{
 public const string Folder="Assets/LighFight/Art/Drafts/TripoPlayable";
 [Serializable]class Role{public string state,path;}[Serializable]class Roles{public Role[] roles;}[Serializable]class Contacts{public FighterView.ContactPose[] contacts;}[Serializable]class Fist{public NativeFingerPose.Joint[] joints;}
 public static void Build(){var args=Environment.GetCommandLineArgs();string modelPath=Arg(args,"-qaTargetModel",Folder+"/Source/Rose/model.fbx");string materialPath=Arg(args,"-qaTargetMaterial","Assets/LighFight/Art/Drafts/TripoRose/native-pbr.mat");BuildAt(modelPath,materialPath);}
 static string Arg(string[] a,string key,string fallback){int n=Array.IndexOf(a,key);return n>=0&&n+1<a.Length?a[n+1]:fallback;}
 public static GameObject BuildAt(string modelPath,string materialPath){Directory.CreateDirectory(Folder);var material=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!material)throw new InvalidOperationException("Supply existing native PBR material using -qaTargetMaterial: "+materialPath);var model=AssetDatabase.LoadAssetAtPath<GameObject>(modelPath);var avatar=AssetDatabase.LoadAllAssetsAtPath(modelPath).OfType<Avatar>().Single(a=>a.isValid&&a.isHuman);var roles=JsonUtility.FromJson<Roles>(File.ReadAllText(Folder+"/candidate-roles.json")).roles.Where(r=>r.state!="sweep").ToArray();var contact=JsonUtility.FromJson<Contacts>(File.ReadAllText(Folder+"/contacts.json")).contacts.Where(c=>c.moveId!="sweep").ToArray();var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Folder+"/candidate.controller");if(!controller)controller=AnimatorController.CreateAnimatorControllerAtPath(Folder+"/candidate.controller");var sm=controller.layers[0].stateMachine;var wanted=new HashSet<string>(roles.Select(r=>r.state));foreach(var existing in sm.states)if(!wanted.Contains(existing.state.name))sm.RemoveState(existing.state);var clips=roles.Select(r=>new FighterView.NativeClip{state=r.state,clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"/Clips/"+Path.GetFileName(r.path))}).ToArray();foreach(var entry in clips){if(!entry.clip||!entry.clip.humanMotion)throw new InvalidOperationException("Missing post-conversion human clip "+entry.state);var state=sm.states.FirstOrDefault(existing=>existing.state.name==entry.state).state;if(!state)state=sm.AddState(entry.state);state.motion=entry.clip;state.iKOnFeet=true;if(entry.state=="Idle")sm.defaultState=state;}
 var root=new GameObject("Rose Humanoid — test candidate (sweep disabled)");try{var rig=UnityEngine.Object.Instantiate(model,root.transform);rig.name="Native Provider Rig";rig.transform.localScale*=2;var animator=rig.GetComponent<Animator>();animator.avatar=avatar;animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();animator.Play("Base Layer.Guard",0,0);animator.Update(0);float bottom=float.PositiveInfinity;foreach(var skin in rig.GetComponentsInChildren<SkinnedMeshRenderer>()){skin.sharedMaterials=skin.sharedMaterials.Select(m=>material).ToArray();skin.updateWhenOffscreen=true;var baked=new Mesh();skin.BakeMesh(baked,true);foreach(var v in baked.vertices)bottom=Mathf.Min(bottom,skin.transform.TransformPoint(v).y);UnityEngine.Object.DestroyImmediate(baked);}rig.transform.localPosition-=Vector3.up*bottom;
 var pose=AssetDatabase.LoadAssetAtPath<NativeFingerPose>(Folder+"/fist.asset");if(!pose){pose=ScriptableObject.CreateInstance<NativeFingerPose>();AssetDatabase.CreateAsset(pose,Folder+"/fist.asset");}pose.sourceAvatar=avatar;pose.sourceClip="Target-specific SDK human finger muscles; external thumb / folded fingers";pose.joints=JsonUtility.FromJson<Fist>(File.ReadAllText(Folder+"/fist-joints.json")).joints;if(pose.joints.Length!=30)throw new Exception("Need30 finger joints");EditorUtility.SetDirty(pose);root.AddComponent<NativeFingerPoseDriver>().Configure(animator,pose,roles.Where(r=>r.state!="palm"&&r.state!="Dance").Select(r=>r.state).ToArray());AddGrounding(root,rig);
 var view=root.AddComponent<FighterView>();view.ConfigureAnimation(animator,contact);view.UseNativeMotion(clips);view.UseSharedMaterials();foreach(var bone in rig.GetComponentsInChildren<Transform>()){if(bone==rig.transform)continue;var original=model.transform.Find(AnimationUtility.CalculateTransformPath(bone,rig.transform));if(original){bone.localPosition=original.localPosition;bone.localRotation=original.localRotation;bone.localScale=original.localScale;}}
 var prefab=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/RoseHumanoidCandidate.prefab");AssetDatabase.SaveAssets();Debug.Log("AGENT_RESULT test-only candidate rebuilt; sweep absent; roles="+clips.Length+" humanAvatar="+avatar.isHuman);return prefab;}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static void ValidateSupportMesh(Mesh mesh){using(var data=new MemoryStream())using(var writer=new BinaryWriter(data)){foreach(var v in mesh.vertices){writer.Write(v.x);writer.Write(v.y);writer.Write(v.z);}foreach(var uv in mesh.uv){writer.Write(uv.x);writer.Write(uv.y);}foreach(var t in mesh.triangles)writer.Write(t);using(var sha=System.Security.Cryptography.SHA256.Create()){string signature=BitConverter.ToString(sha.ComputeHash(data.ToArray())).Replace("-","").ToLowerInvariant();if(signature!="a448b36a2c7ae0ba9099159c8116a126ea10a064b449a487deb2f6abb7f43478")throw new InvalidOperationException("Rose support original vertex order/UV/topology changed");}}}
 static void AddGrounding(GameObject actor,GameObject native){var skin=native.GetComponentInChildren<SkinnedMeshRenderer>();var grounding=actor.AddComponent<CandidateFootGrounding>();grounding.nativeRig=native.transform;grounding.nativeRest=native.transform.localPosition;grounding.bones=skin.bones;var points=new List<CandidateFootGrounding.Point>();var mesh=skin.sharedMesh;var vertices=mesh.vertices;var binds=mesh.bindposes;var supports=new HashSet<int>(File.ReadAllLines(Folder+"/sole-support-native-vertex-indices.txt").Where(line=>!string.IsNullOrWhiteSpace(line)).Select(int.Parse));if(mesh.vertexCount!=56145||mesh.triangles.Length/3!=100000||skin.bones.Length!=67||supports.Count!=152||supports.Any(v=>v<0||v>=mesh.vertexCount))throw new InvalidOperationException("Rose support mesh/index packet changed");ValidateSupportMesh(mesh);using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int v=0;v<vertices.Length;v++){var influences=new List<CandidateFootGrounding.Influence>();for(int n=0;n<counts[v];n++){var w=weights[offset+n];influences.Add(new CandidateFootGrounding.Influence{bone=w.boneIndex,weight=w.weight,bindPoint=binds[w.boneIndex].MultiplyPoint3x4(vertices[v])});}if(supports.Contains(v))points.Add(new CandidateFootGrounding.Point{influences=influences.ToArray()});offset+=counts[v];}}grounding.shoePoints=points.ToArray();Debug.Log("Shoe proxy skin samples="+points.Count);}

}
}
